mapper.update:
update pro_route_product_bom set del_flag = '1'
where del_flag = '0'
  and product_id = #{productId}
  and route_id = #{routeId}

mapper.select:
select b.record_id, b.route_id, b.process_id, b.product_id, b.item_id, b.item_code, b.item_name, b.specification, b.unit_of_measure, b.quantity, b.del_flag, b.remark, b.create_by, b.create_time, b.update_by, b.update_time from pro_route_product_bom b left join pro_route_process rp on rp.route_id = b.route_id and rp.process_id = b.process_id and rp.del_flag = '0'
b.del_flag = '0' and b.product_id = #{productId} and b.route_id = #{routeId}
order by rp.order_num asc, b.item_code asc

select

from pro_route_product_bom b

    b.del_flag = '0'
    and b.route_id = #{routeId}
    and b.process_id = #{processId}
    and b.product_id = #{productId}

order by b.item_code asc
